    /// <summary>
    /// check if transfer order is picked or not 
    /// </summary>
    /// <param name = "_transferId">_transferId</param>
    /// <returns>boolean</returns>
    static boolean METTransferOrderNotPicked(InventTransferId _transferId)
    {
        InventTransferTable   inventTransferTableNotPicked;
        WMSPickingRoute wmsPickingRoute;

        if (!_transferId)
        {
            return false;
        }

        
        select firstonly RecId from inventTransferTableNotPicked
                    where inventTransferTableNotPicked.TransferId == _transferId
              exists join wmsPickingRoute
                    where wmsPickingRoute.transRefId == _transferId
                         && wmsPickingRoute.expeditionStatus !=  WMSExpeditionStatus::Complete;


        return (inventTransferTableNotPicked.RecId != 0);
    }

    /// <summary>
    ///    Sets the value of the <c>TransferStatus</c> field so that it reflects the highest status for all
    ///    lines.
    /// </summary>
    /// <remarks>
    ///    If the order has no lines, the <c>TransferStatus</c> field is set to a value of
    ///    <c>InventTransferStatus::Created</c>.
    /// </remarks>
    public void setInventTransferStatus()
    {
        next setInventTransferStatus();

        switch (this.TransferStatus)
        {
            case InventTransferStatus::Shipped:
                this.sendTransferOrderFinalisationBusinessEvent();
                break;
            case InventTransferStatus::Received:
                METTransferOrderReceivedBusinessEvent::newFromInventTransferTable(this).send();
                break;
            default:
                break;
        }
    }

    /// <summary>
    /// Raises the <c>METTransferOrderFinalisationBusinessEvent</c>
    /// If the business event is enabled and the transfer type is not cross-dock.
    /// </summary>
    private void sendTransferOrderFinalisationBusinessEvent()
    {
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METTransferOrderFinalisationBusinessEvent)))
        {
            WHSParameters               whsParameters   = WHSParameters::find();
            InventLocation              inventLocation  = InventLocation::find(this.InventLocationIdTo);
            METInventTransferTableExt   metInventTransferTableExt;

            select firstonly metInventTransferTableExt
                where metInventTransferTableExt.InventTransferTable == this.RecId
                   && metInventTransferTableExt.TransferType == METCrossDockTransferType::None;

            if (metInventTransferTableExt && inventLocation.METWHSubEntity != whsParameters.METCampbellSubEntityIndustryKey)
            {
                METTransferOrderFinalisationBusinessEvent::newFromInventTransferTable(this).send();
            }
        }
    }

    /// <summary>
    /// Raises the <c>METTransferOrderFinalisationBusinessEvent</c> for Campbell sub-entity
    /// If the business event is enabled and the destination location matches.
    /// Created for Task 282558: CB913/CB162 - Campbells Transfer Order Receipt [D365F&O] [Storeline]
    /// </summary>
    private void sendTransferOrderReceivedBusinessEvent()
    {
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METTransferOrderReceivedBusinessEvent)))
        {
            WHSParameters   whsParameters   = WHSParameters::find();
            InventLocation  inventLocation  = InventLocation::find(this.InventLocationIdTo);

            if (inventLocation.METWHSubEntity == whsParameters.METCampbellSubEntityIndustryKey)
            {
                METTransferOrderReceivedBusinessEvent::newFromInventTransferTable(this).send();
            }
        }
    }

